<?php
namespace Tests\Feature;
use App\Services\Licensing\Kslp\KslpLicenseControlPlane; use App\Services\Licensing\Kslp\KslpSigner; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Carbon; use Tests\TestCase;
final class KslpLifecycleTest extends TestCase {use RefreshDatabase;
 public function test_trial_activation_idempotency_transfer_and_states():void{$c=app(KslpLicenseControlPlane::class);$l=$c->issue("cust-1","trial","owner");self::assertSame(30.0,Carbon::parse($l["starts_at"])->diffInDays(Carbon::parse($l["expires_at"])));$a=$c->activate($l["id"],"ed25519:server_identity_0000000001",str_repeat("a",64),"retry-1","owner");$again=$c->activate($l["id"],"ed25519:server_identity_0000000001",str_repeat("a",64),"retry-1","owner");self::assertSame($a["id"],$again["id"]);self::assertSame("ACTIVE",$c->state($l["id"],Carbon::parse($l["starts_at"])->addDay()));$b=$c->transfer($l["id"],"ed25519:server_identity_0000000002",str_repeat("b",64),"retry-2","owner","replacement");self::assertNotSame($a["id"],$b["id"]);$this->assertDatabaseCount("kslp_license_events",4);}
 public function test_trial_cannot_reset_and_revoke_reactivate_plan_change_work():void{$c=app(KslpLicenseControlPlane::class);$l=$c->issue("cust-2","trial","owner");try{$c->issue("cust-2","trial","owner");self::fail();}catch(\DomainException $e){self::assertSame("KSLP_TRIAL_ALREADY_USED",$e->getMessage());}$c->changePlan($l["id"],"professional","owner","paid");$c->revoke($l["id"],"owner","security");self::assertSame("REVOKED",$c->state($l["id"]));$c->reactivate($l["id"],"owner","cleared");self::assertNotSame("REVOKED",$c->state($l["id"]));}
 public function test_signed_lease_is_server_bound():void{$c=app(KslpLicenseControlPlane::class);$l=$c->issue("cust-3","business","owner");$a=$c->activate($l["id"],"ed25519:server_identity_0000000003",str_repeat("c",64),"retry-3","owner");$kp=sodium_crypto_sign_keypair();$sk=sodium_crypto_sign_secretkey($kp);$signer=new class($sk) implements KslpSigner{public function __construct(private string $sk){}public function kid():string{return "test-kid";}public function sign(string $m):string{return sodium_crypto_sign_detached($m,$this->sk);}};$token=$c->lease($l["id"],$a["id"],$signer,["hosting"=>true],["nodes"=>3]);self::assertSame(3,count(explode(".",$token)));}
}
